namespace NC070_LFUCache;

public class SolutionTests
{
    [Fact]
    public void Example1()
    {
        var c = new LFUCache(2);
        c.Put(1, 1);
        c.Put(2, 2);
        Assert.Equal(1, c.Get(1));
        c.Put(3, 3); // evicts 2 (freq 1)
        Assert.Equal(-1, c.Get(2));
        Assert.Equal(3, c.Get(3));
        c.Put(4, 4); // 1 and 3 both freq 2, 1 is LRU -> evict 1
        Assert.Equal(-1, c.Get(1));
        Assert.Equal(3, c.Get(3));
        Assert.Equal(4, c.Get(4));
    }
    [Fact]
    public void PutUpdatesFrequency()
    {
        var c = new LFUCache(2);
        c.Put(1, 1);
        c.Put(2, 2);
        c.Put(1, 5);   // freq(1) = 2
        c.Put(3, 3);   // evicts 2
        Assert.Equal(-1, c.Get(2));
        Assert.Equal(5, c.Get(1));
        Assert.Equal(3, c.Get(3));
    }
}